UPDATE `wp_postmeta` SET `meta_value` = 'نگهداری پایه شامل چه مواردی است؟ | به‌روزرسانی WordPress، پشتیبان‌گیری روزانه، پایش امنیتی و گزارش‌های ماهانه.\r\nچقدر سریع به موارد اضطراری پاسخ می‌دهید؟ | ظرف 2 ساعت برای مسائل بحرانی و 24 ساعت برای مسائل غیربحرانی.\r\nآیا محتوا را هم به‌روزرسانی می‌کنید؟ | بله، به‌روزرسانی محتوا در پلن‌های ویژه ما گنجانده شده یا به‌صورت ساعتی در دسترس است.\r\nاگر سایت من هک شود چه؟ | ما بلافاصله و بدون هزینه اضافی برای مشتریان نگهداری، آن را پاک‌سازی می‌کنیم.\r\nآیا می‌توانم پلن خود را ارتقا/کاهش دهم؟ | بله، می‌توانید هر زمان با 30 روز اطلاع قبلی پلن خود را تغییر دهید.\r\nآیا روی سایت‌های غیر وردپرسی هم کار می‌کنید؟ | بله، ما تمام انواع وب‌سایت‌ها از جمله اپلیکیشن‌های سفارشی را نگهداری می‌کنیم.' WHERE `meta_id` = 205;
